void CRes::SetPtn(float s1, float s2, float s3)
{
	switch(DegF){
		case 0:		// 水平パターン
			PtnH[0][Voff] = s1; 	// 垂直偏波
			PtnH[1][Voff] = s2;		// 水平偏波
			PtnH[2][Voff] = s3;		// 合算値
			break;
		case 1:		// 垂直パターン
			PtnV[0][Voff] = s1;
			PtnV[1][Voff] = s2;
			PtnV[2][Voff] = s3;
			break;
		case 2:		// 垂直詳細パターン
			if( MaxEV < s3 ){
				PtnV[0][DegV] = s1;
				PtnV[1][DegV] = s2;
				PtnV[2][DegV] = s3;
				MaxEV = s3;
				Elv = double(Voff)/10.0;
			}
			break;
	}
	Voff++;
}

int CRes::GetHMAX(void)
{
	double F = -999999;
	DegH = 0;
	int N = 360/PtnF;
	for( int i = 0; i < N; i++ ){
		if( F < PtnH[2][i] ){
			F = PtnH[2][i];
			DegH = i;
		}
	}
	return DegH * PtnF;
}

int CRes::GetVMAX(void)
{
	MaxV = -999999;
	DegV = 0;
	int N = 180/PtnF;
	for( int i = 0; i <= N; i++ ){
		if( (MaxV < PtnV[2][i]) || ((i>(N/2))&&(MaxV==PtnV[2][i])) ){
			MaxV = PtnV[2][i];
			DegV = i;
		}
	}
	return DegV * PtnF;
}

double CRes::GetAdjElv(void)
{
	double vv = GetElv();
	if( !env.type && exeenv.FixFreeAngle ){
		vv = 0.0;
	}
	else {
		if( vv >= 87.0 ) vv = 45.0;
	}
	ElvHPtn = vv;
	return vv;
}

void CRes::CalcPtn(void)
{
	int i;
	MaxVP = PtnH[0][0];
	MaxHP = PtnH[1][0];
	MaxH = PtnH[2][0];
	DegH = 0;
	int N = 360/PtnF;
	for( i = 1; i < N; i++ ){
		if( MaxVP < PtnH[0][i] ){
			MaxVP = PtnH[0][i];
		}
		if( MaxHP < PtnH[1][i] ){
			MaxHP = PtnH[1][i];
		}
		if( MaxH < PtnH[2][i] ){
			MaxH = PtnH[2][i];
			DegH = i;
		}
	}
	MaxG = MaxV;
	if( MaxG < MaxEV ) MaxG = MaxEV;
	if( MaxG < MaxH ) MaxG = MaxH;
	Res[RWp].GAIN = MaxG;
	CalcFB();
	if( Elv >= 90 ) Elv = 180 - Elv;
#if 0
	ElvHPtn = Elv;
	if( !env.type && env.FixFreeAngle ){
		ElvHPtn = 0.0;
	}
	else {
		if( ElvHPtn >= 87.0 ) ElvHPtn = 45.0;
	}
#endif
	Res[RWp].ELV = Elv;
	Res[RWp].MAXVP = MaxVP;
	Res[RWp].MAXHP = MaxHP;
}

// ゲインの再計算
void CRes::ReCalcGain(void)
{
	int i;
	MaxVP = PtnH[0][0];
	MaxHP = PtnH[1][0];
	MaxH = PtnH[2][0];
	DegH = 0;
	int N = 360/PtnF;
	for( i = 1; i < N; i++ ){
		if( MaxVP < PtnH[0][i] ){
			MaxVP = PtnH[0][i];
		}
		if( MaxHP < PtnH[1][i] ){
			MaxHP = PtnH[1][i];
		}
		if( MaxH < PtnH[2][i] ){
			MaxH = PtnH[2][i];
			DegH = i;
		}
	}
	MaxG = MaxV;
	if( MaxG < MaxEV ) MaxG = MaxEV;
	if( MaxG < MaxH ) MaxG = MaxH;
	Res[RWp].GAIN = MaxG;
	CalcFB();
	Res[RWp].MAXVP = MaxVP;
	Res[RWp].MAXHP = MaxHP;
}

void CRes::CalcFB(void)
{
	int i;

	float BD = PtnH[2][180/PtnF];
	if( env.fbr ){					// バック側の範囲の最大を得る
		int fbrh = env.fbr & 0x0000ffff;
		int fbrv = (env.fbr >> 16) & 0x0000ffff;
		// 水平のチェック
		int n = (180 - (fbrh/2))/PtnF;
		for( i = 0; i <= fbrh; i+=PtnF, n++ ){
			if( BD < PtnH[2][n] ) BD = PtnH[2][n];
		}
		// 垂直のチェック
		for( i = n = 0; i <= fbrv; i+=PtnF, n++ ){
			if( BD < PtnV[2][n] ) BD = PtnV[2][n];
		}
	}
	Res[RWp].FB = PtnH[2][0] - BD;
}
void CRes::ClearCur(void)
{
	for( int i = 0; i < env.pmax; i++ ){
		Cur[i] = NULLF;
		CurDir[i] = 0;
	}
	RealMax = ImgMax = 0.0;
}

void CRes::SetCur(ANTDEF *ap, int n, double r, double j, double d)
{
	if( n < ap->wzmax ){
		if( ap->wzdef[n].PNo ){					// パルスが存在する時
			n = ap->wzdef[n].PNo - 1;
			if( Cur[n] == NULLF ){
				SetCurDir(n, r, j);
				Cur[n] = d;
			}
		}
	}
}
